def t(f):
    try:
        print(repr(f()))
    except Exception as e:
        print(type(e).__name__ + ':', e)
def x(src):
    "Runs src and shows the names it binds, or the error."
    ns = {}
    try: exec(src, ns)
    except SyntaxError as e: print(type(e).__name__ + ":", e.msg, "<-", repr(src)); return
    except Exception as e: print(type(e).__name__ + ":", e, "<-", repr(src)); return
    print({k: v for k, v in ns.items() if k != "__builtins__" and not callable(v) and type(v).__name__ != "module"}, "<-", repr(src))
def ev(src):
    try: print(repr(eval(src)), end=" | ")
    except SyntaxError as e: print("SyntaxError:", e.msg, "<-", src, end=" | ")
